<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Activity, ArrowUpRight, Boxes, Check, ChevronDown, CircleHelp, Command, Gamepad2, LayoutDashboard, ListChecks, LogOut, MessageSquareText, Plus, Radio, Search, Server, Settings2, Shield, Trash2, UserRound, Users, X } from '@lucide/vue'

type Kind = 'adapters' | 'servers' | 'players' | 'social-accounts' | 'groups' | 'whitelist' | 'blacklist' | 'commands' | 'ai-providers' | 'image-templates' | 'plugins' | 'settings' | 'sync-rules' | 'chat-images' | 'placeholders' | 'player-statistics' | 'skins'
type Entry = { id: string; kind: Kind; name: string; detail: string; enabled: boolean; createdAt: string; updatedAt: string }
type LogEntry = { time: string; level: string; source: string; message: string }
const nav = [
  { id: 'overview', label: '概览', icon: LayoutDashboard, group: '概览' },
  { id: 'adapters', label: '平台适配器', icon: Radio, group: '接入', kind: 'adapters' as Kind },
  { id: 'servers', label: 'Minecraft 服务器', icon: Gamepad2, group: '接入', kind: 'servers' as Kind },
  { id: 'groups', label: '群组', icon: MessageSquareText, group: '消息', kind: 'groups' as Kind },
  { id: 'sync-rules', label: '同步规则', icon: Boxes, group: '消息', kind: 'sync-rules' as Kind },
  { id: 'players', label: '玩家与绑定', icon: Users, group: '玩家', kind: 'players' as Kind },
  { id: 'whitelist', label: '白名单', icon: ListChecks, group: '玩家', kind: 'whitelist' as Kind },
  { id: 'blacklist', label: '黑名单', icon: Shield, group: '玩家', kind: 'blacklist' as Kind },
  { id: 'commands', label: '命令', icon: Command, group: '自动化', kind: 'commands' as Kind },
  { id: 'logs', label: '运行日志', icon: Activity, group: '运维' },
]
const selected = ref('overview'), entries = ref<Entry[]>([]), adapters = ref<Entry[]>([]), servers = ref<Entry[]>([]), logs = ref<LogEntry[]>([]), counts = ref<Record<string, number>>({}), loading = ref(false), error = ref(''), toast = ref(''), query = ref(''), modal = ref(false), apiOnline = ref(false), updatedAt = ref('')
const authChecked = ref(false), authenticated = ref(false), setupRequired = ref(false), authBusy = ref(false), authError = ref(''), authUsername = ref(''), authPassword = ref('')
const editing = ref<Entry | null>(null), name = ref(''), detail = ref('{}'), enabled = ref(true), adapterType = ref('Onebot11')
const current = computed(() => nav.find(item => item.id === selected.value)!), kind = computed(() => current.value.kind), title = computed(() => current.value.label)
const filtered = computed(() => entries.value.filter(item => `${item.name} ${item.detail}`.toLowerCase().includes(query.value.toLowerCase())))
const groups = ['概览', '接入', '消息', '玩家', '自动化', '运维']
const descriptions: Record<string, string> = { adapters: '平台连接配置。连接测试和运行时生命周期仍在移植。', servers: 'Minecraft 实例配置。桥接端连接能力仍在移植。', players: '玩家资料与社交账号绑定记录。', groups: '适配器发现的社交群组。', whitelist: '服务器准入名单。', blacklist: '封禁账号与备注。', commands: '自定义命令定义。命令执行引擎仍在移植。', settings: '实例级运行参数。', 'sync-rules': '群与服务器之间的消息路由规则。' }
const recentActivity = computed(() => [...logs.value].sort((a, b) => Date.parse(b.time) - Date.parse(a.time)).slice(0, 5))
const dashboardStats = computed(() => [
  { label: '平台适配器', value: counts.value.adapters ?? 0, note: '已保存配置', icon: Radio, tone: 'mint' },
  { label: 'Minecraft 服务器', value: counts.value.servers ?? 0, note: '服务器配置', icon: Server, tone: 'blue' },
  { label: '玩家资料', value: counts.value.players ?? 0, note: '已登记玩家', icon: UserRound, tone: 'amber' },
  { label: '自定义命令', value: counts.value.commands ?? 0, note: '命令配置', icon: Command, tone: 'rose' },
])
function formatAdapterType(item: Entry) { try { return JSON.parse(item.detail || '{}').adapterType ?? '社交平台适配器' } catch { return '社交平台适配器' } }
async function api<T>(url: string, init?: RequestInit): Promise<T> { const key = sessionStorage.getItem('easybotApiKey'); const response = await fetch(url, { ...init, credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...(key ? { Authorization: `Bearer ${key}` } : {}), ...init?.headers } }); if (!response.ok) { if (response.status === 401 && !url.startsWith('/api/auth/')) authenticated.value = false; const body = await response.json().catch(() => ({})); throw new Error(body.message ?? `请求失败 (${response.status})`) } if (response.status === 204) return undefined as T; return response.json() as Promise<T> }
async function load() { if (selected.value === 'logs') { loading.value = true; try { logs.value = await api<LogEntry[]>('/api/logs?limit=200') } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } finally { loading.value = false }; return } if (!kind.value) return; loading.value = true; error.value = ''; try { entries.value = await api<Entry[]>(`/api/records?kind=${kind.value}`) } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } finally { loading.value = false } }
async function dashboard() { try { const [summary, adapterItems, serverItems, recent] = await Promise.all([api<{ counts: Record<string, number> }>('/api/dashboard/data'), api<Entry[]>('/api/adapter/list'), api<Entry[]>('/api/records?kind=servers'), api<LogEntry[]>('/api/logs?limit=200')]); counts.value = summary.counts; adapters.value = adapterItems; servers.value = serverItems; logs.value = recent; apiOnline.value = true; updatedAt.value = new Date().toLocaleTimeString('zh-CN'); error.value = '' } catch { apiOnline.value = false; updatedAt.value = '' } }
async function initializeConsole() { try { const setup = await api<{ initialized: boolean }>('/api/setup/status'); setupRequired.value = !setup.initialized; if (setup.initialized) { const session = await api<{ authenticated: boolean }>('/api/auth/session'); authenticated.value = session.authenticated || Boolean(sessionStorage.getItem('easybotApiKey')) } authChecked.value = true; if (authenticated.value) { void dashboard(); void load() } } catch (e) { authError.value = e instanceof Error ? e.message : '无法连接 Go API'; authChecked.value = true } }
async function submitAuth() { authBusy.value = true; authError.value = ''; try { await api(setupRequired.value ? '/api/setup/admin' : '/api/auth/login', { method: 'POST', body: JSON.stringify({ username: authUsername.value, password: authPassword.value }) }); authPassword.value = ''; authenticated.value = true; setupRequired.value = false; void dashboard(); void load() } catch (e) { authError.value = e instanceof Error ? e.message : '身份验证失败' } finally { authBusy.value = false } }
watch(selected, () => { query.value = ''; if (!authenticated.value) return; if (selected.value === 'overview') void dashboard(); else void load() })
let logRefresh: number | undefined
onMounted(() => { void initializeConsole(); logRefresh = window.setInterval(() => { if (!apiOnline.value || !authenticated.value) return; if (selected.value === 'overview') void dashboard(); else if (selected.value === 'logs') void api<LogEntry[]>('/api/logs?limit=200').then(items => logs.value = items).catch(() => {}) }, 15000) })
onUnmounted(() => { if (logRefresh) window.clearInterval(logRefresh) })
function openDocs() { window.open('https://docs.inectar.cn/docs/easybot/intro', '_blank', 'noopener') }
function configureKey() { const value = prompt('输入 EASYBOT_API_KEY；留空可清除当前会话密钥。', sessionStorage.getItem('easybotApiKey') ?? ''); if (value === null) return; if (value) sessionStorage.setItem('easybotApiKey', value); else sessionStorage.removeItem('easybotApiKey'); error.value = ''; void dashboard(); void load() }
async function signOut() { try { await api('/api/auth/logout', { method: 'POST' }) } catch { /* Local state still needs to close if the service is unavailable. */ } sessionStorage.removeItem('easybotApiKey'); authenticated.value = false; authUsername.value = ''; authPassword.value = '' }
function newEntry() { editing.value = null; name.value = ''; enabled.value = true; adapterType.value = 'Onebot11'; detail.value = kind.value === 'adapters' ? '{\n  "url": "ws://127.0.0.1:3001"\n}' : '{}'; modal.value = true }
function edit(item: Entry) { editing.value = item; name.value = item.name; detail.value = item.detail; enabled.value = item.enabled; modal.value = true }
async function save() { if (!kind.value || !name.value.trim()) return; error.value = ''; try { JSON.parse(detail.value); let saved: Entry
  if (kind.value === 'adapters') saved = editing.value ? await api<Entry>(`/api/adapter/${editing.value.id}`, { method: 'PUT', body: JSON.stringify({ displayName: name.value.trim(), configJson: detail.value }) }) : await api<Entry>('/api/adapter/create', { method: 'POST', body: JSON.stringify({ adapterType: adapterType.value, displayName: name.value.trim(), configJson: detail.value }) })
  else { const body = { kind: kind.value, name: name.value.trim(), detail: detail.value, enabled: enabled.value }; saved = editing.value ? await api<Entry>(`/api/records/${kind.value}/${editing.value.id}`, { method: 'PUT', body: JSON.stringify(body) }) : await api<Entry>('/api/records', { method: 'POST', body: JSON.stringify(body) }) }
  entries.value = editing.value ? entries.value.map(item => item.id === saved.id ? saved : item) : [saved, ...entries.value]; modal.value = false; toast.value = editing.value ? '配置已保存' : '配置已创建'; setTimeout(() => toast.value = '', 2200); void dashboard()
} catch (e) { error.value = e instanceof Error ? e.message : '保存失败' } }
async function remove(item: Entry) { if (!kind.value || !confirm(`删除“${item.name}”？`)) return; try { await api(`/api/records/${kind.value}/${item.id}`, { method: 'DELETE' }); entries.value = entries.value.filter(row => row.id !== item.id); void dashboard() } catch (e) { error.value = e instanceof Error ? e.message : '删除失败' } }
async function toggle(item: Entry) { try { const updated = await api<Entry>(`/api/records/${item.kind}/${item.id}`, { method: 'PUT', body: JSON.stringify({ name: item.name, detail: item.detail, enabled: !item.enabled }) }); entries.value = entries.value.map(row => row.id === updated.id ? updated : row) } catch (e) { error.value = e instanceof Error ? e.message : '更新失败' } }
async function startAdapter(item: Entry) { try { await api(`/api/adapter/${item.id}/start`, { method: 'POST' }) } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } }
</script>

<template>
  <div v-if="!authChecked" class="auth-screen"><div class="auth-panel"><img src="/brand.svg" alt="EasyBot" /><p>正在连接 EasyBot 服务…</p></div></div>
  <div v-else-if="!authenticated" class="auth-screen"><section class="auth-panel"><img src="/brand.svg" alt="EasyBot" /><p class="auth-kicker">EASYBOT CONTROL CENTER</p><h1>{{ setupRequired ? '初始化管理员' : '管理员登录' }}</h1><p class="auth-description">{{ setupRequired ? '创建首个管理员账户以保护控制台。此操作仅允许从本机完成。' : '登录以管理平台接入与 Minecraft 服务。' }}</p><div v-if="authError" class="auth-error">{{ authError }}</div><form class="auth-form" @submit.prevent="submitAuth"><label class="field">用户名<input v-model="authUsername" required minlength="3" maxlength="32" autocomplete="username" placeholder="管理员用户名" /></label><label class="field">密码<input v-model="authPassword" required :minlength="setupRequired ? 12 : 1" maxlength="72" :autocomplete="setupRequired ? 'new-password' : 'current-password'" type="password" :placeholder="setupRequired ? '至少 12 个字符' : '输入密码'" /></label><button class="btn-primary auth-submit" type="submit" :disabled="authBusy">{{ authBusy ? '请稍候…' : setupRequired ? '创建管理员并进入' : '登录控制台' }}</button></form></section></div>
  <div v-else class="app-shell flex min-h-screen bg-[#f3f6f7] text-[#26343a]">
    <aside class="sidebar fixed inset-y-0 left-0 z-10 flex w-[248px] flex-col px-3 py-5 text-[#d8e0e2]">
      <div class="brand mb-6 flex items-center gap-2.5 px-2"><img src="/brand.svg" alt="EasyBot" class="brand-mark size-8" /><span class="flex flex-col"><b class="text-[15px] text-white">EasyBot</b><small class="text-[11px] text-[#96a7ad]">社区管理控制台</small></span><span class="ml-auto rounded-sm bg-[#31424b] px-1.5 py-0.5 text-[11px] text-[#aebbc0]">DEV</span></div>
      <div class="instance-switch mb-4 flex items-center gap-2 rounded-md p-2"><img src="/brand.svg" alt="" class="size-7" /><span class="flex flex-1 flex-col"><b class="text-[13px] text-white">本地实例</b><small class="text-[11px] text-[#99a7ac]">管理控制台</small></span><ChevronDown :size="14" /></div>
      <nav class="flex-1 overflow-auto"> <template v-for="group in groups" :key="group"><p class="px-2 pb-1 pt-4 text-[13px] text-[#84949a]">{{ group }}</p><button v-for="item in nav.filter(entry => entry.group === group)" :key="item.id" class="nav-link flex h-[34px] w-full items-center gap-2.5 rounded px-2 text-left text-[13px] text-[#bac5c8] hover:bg-[#243740] hover:text-white" :class="{ chosen: selected === item.id }" @click="selected = item.id"><component :is="item.icon" :size="16" /><span>{{ item.label }}</span><small v-if="item.kind === 'adapters' && counts.adapters" class="ml-auto">{{ counts.adapters }}</small></button></template></nav>
      <div class="sidebar-footer flex items-center gap-2 px-2 pt-3 text-[12px]"><i class="size-1.5 rounded-full" :class="apiOnline ? 'bg-[#45bd85]' : 'bg-[#d28564]'"></i>{{ apiOnline ? '服务在线' : '服务离线' }}<span class="ml-auto text-[11px] text-[#829198]">0.1.0-dev</span></div>
    </aside>
    <main class="main-area ml-[248px] min-h-screen flex-1">
      <header class="topbar sticky top-0 z-[5] flex h-[60px] items-center justify-between px-7"><div class="flex items-center gap-3 text-[13px] text-[#879398]"><span>工作区</span><span class="text-[#c2cbce]">/</span><b class="text-[#3c4a51]">{{ title }}</b></div><div class="flex items-center gap-3"><button class="icon-btn" title="查看文档" @click="openDocs"><CircleHelp :size="17" /></button><span class="h-5 border-l border-[#e5e9ea]"></span><button class="flex items-center gap-2 text-[13px] text-[#5b686e]" title="配置管理 API Key" @click="configureKey"><i class="grid size-7 place-items-center rounded bg-[#e8efeb] not-italic font-semibold text-[#52866b]">A</i>管理员<ChevronDown :size="13" /></button><button class="icon-btn" title="退出登录" @click="signOut"><LogOut :size="16" /></button></div></header>
      <div class="page-wrap mx-auto w-full max-w-[1560px] p-7 max-sm:p-3">
        <section v-if="selected === 'overview'">
          <div class="page-heading mb-5 flex items-center justify-between gap-4"><div><div class="eyebrow mb-1.5">EASYBOT CONTROL CENTER</div><h1 class="text-[25px] font-semibold tracking-normal">运行总览</h1><p class="mt-1 text-[13px] text-[#7d898e]">社区接入与 Minecraft 服务配置</p></div><div class="flex items-center gap-3"><span class="api-state" :class="apiOnline ? 'is-online' : 'is-offline'"><i></i>{{ apiOnline ? 'API 在线' : 'API 离线' }}</span><button class="btn-secondary" @click="dashboard"><Activity :size="15" />刷新状态</button></div></div>
          <div v-if="error" class="mb-4 flex items-center gap-2 rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]"><X :size="15" />{{ error }}<button class="ml-auto" @click="error = ''"><X :size="14" /></button></div>
          <div class="mb-4 flex flex-wrap items-center justify-between gap-2 text-[12px] text-[#718087]"><span>配置概况</span><span>最近同步 {{ updatedAt || '等待服务连接' }}</span></div>
          <div class="stats-grid mb-5 grid grid-cols-4 gap-3 max-lg:grid-cols-2 max-sm:grid-cols-1">
            <article v-for="stat in dashboardStats" :key="stat.label" class="stat-card"><span class="stat-icon" :class="stat.tone"><component :is="stat.icon" :size="18" /></span><div class="min-w-0"><span class="stat-label">{{ stat.label }}</span><strong>{{ stat.value }}</strong><small>{{ stat.note }}</small></div><ArrowUpRight :size="15" class="stat-arrow" /></article>
          </div>
          <div class="dashboard-grid grid grid-cols-[1.15fr_0.85fr] gap-4 max-lg:grid-cols-1">
            <section class="panel"><div class="panel-heading"><div><h2>接入配置</h2><p>社交平台与游戏服务器</p></div><button class="text-link" @click="selected='adapters'">管理配置 <ArrowUpRight :size="14" /></button></div><div class="connection-list divide-y divide-[#edf0f1]">
              <div v-for="item in [...adapters.map(row => ({ ...row, category: '平台适配器', icon: Radio, detailText: formatAdapterType(row) })), ...servers.map(row => ({ ...row, category: 'Minecraft 服务器', icon: Gamepad2, detailText: '桥接端配置' }))]" :key="item.id" class="connection-row"><span class="connection-icon"><component :is="item.icon" :size="17" /></span><span class="min-w-0 flex-1"><b>{{ item.name }}</b><small>{{ item.category }} · {{ item.detailText }}</small></span><span class="status pending"><i></i>{{ item.category === '平台适配器' ? '运行时待接入' : '等待连接' }}</span></div>
              <div v-if="adapters.length + servers.length === 0" class="dashboard-empty"><span class="empty-mark"><img src="/brand.svg" alt="" /></span><b>还没有接入配置</b><p>先添加平台适配器或 Minecraft 服务器。</p><div class="mt-3 flex justify-center gap-2"><button class="btn-secondary compact" @click="selected='adapters'; newEntry()"><Plus :size="14" />添加适配器</button><button class="btn-primary compact" @click="selected='servers'; newEntry()"><Plus :size="14" />添加服务器</button></div></div>
            </div></section>
            <section class="panel"><div class="panel-heading"><div><h2>最近活动</h2><p>服务记录与配置变更</p></div><button class="text-link" @click="selected='logs'">查看日志 <ArrowUpRight :size="14" /></button></div><div v-if="recentActivity.length" class="activity-list divide-y divide-[#edf0f1]"><div v-for="(item, index) in recentActivity" :key="`${item.time}-${index}`" class="activity-row"><i :class="`activity-dot level-${item.level}`"></i><span class="min-w-0 flex-1"><b>{{ item.message }}</b><small>{{ item.source }}</small></span><time>{{ new Date(item.time).toLocaleTimeString('zh-CN') }}</time></div></div><div v-else class="dashboard-empty activity-empty"><span class="empty-mark quiet"><Activity :size="19" /></span><b>{{ apiOnline ? '暂无活动记录' : '等待服务连接' }}</b><p>{{ apiOnline ? '服务事件和配置操作会显示在这里。' : '连接 Go API 后显示服务状态与最近事件。' }}</p></div></section>
          </div>
          <section class="setup-panel mt-4"><div class="panel-heading"><div><h2>快速开始</h2><p>按步骤完成基础接入</p></div></div><div class="setup-grid grid grid-cols-4 gap-2 max-md:grid-cols-2 max-sm:grid-cols-1">
            <button class="setup-step" @click="selected='adapters'; if (adapters.length === 0) newEntry()"><span>01</span><b>连接社交平台</b><small>{{ adapters.length ? `${adapters.length} 个配置已保存` : '添加 OneBot / Milky / Telegram' }}</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='servers'; if (servers.length === 0) newEntry()"><span>02</span><b>添加 Minecraft</b><small>{{ servers.length ? `${servers.length} 个实例已保存` : '配置服务器与 Bridge' }}</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='groups'"><span>03</span><b>检查群组</b><small>查看已发现的聊天群组</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='sync-rules'; if (counts['sync-rules'] === 0) newEntry()"><span>04</span><b>设置消息同步</b><small>{{ counts['sync-rules'] ? `${counts['sync-rules']} 条规则已保存` : '创建群服消息路由' }}</small><ArrowUpRight :size="14" /></button>
          </div></section>
        </section>
        <section v-else-if="selected === 'logs'">
          <div class="mb-5 flex items-end justify-between"><div><div class="mb-1.5 text-[13px] text-[#89959a]">系统</div><h1 class="text-2xl font-semibold tracking-normal">运行日志</h1></div><button class="btn-secondary" @click="load"><Activity :size="15" />刷新</button></div>
          <div v-if="loading" class="empty">正在读取日志…</div>
          <div v-else-if="logs.length" class="overflow-x-auto rounded-md border border-[#e4e9ea] bg-white"><table class="w-full min-w-[640px] border-collapse text-left"><thead class="bg-[#fafbfb] text-[13px] text-[#879398]"><tr><th>时间</th><th>级别</th><th>来源</th><th>事件</th></tr></thead><tbody><tr v-for="(item, index) in logs" :key="`${item.time}-${index}`" class="border-t border-[#edf0f1]"><td class="whitespace-nowrap text-[13px] text-[#89959a]">{{ new Date(item.time).toLocaleString('zh-CN') }}</td><td><span class="log-level" :class="`level-${item.level}`">{{ item.level.toUpperCase() }}</span></td><td class="text-[13px] text-[#718087]">{{ item.source }}</td><td class="font-mono text-[13px] text-[#48565c]">{{ item.message }}</td></tr></tbody></table></div>
          <div v-else class="empty"><b>暂无运行日志</b><p>API 操作和服务生命周期事件会显示在这里。</p></div>
        </section>
        <section v-else>
          <div class="mb-6 flex items-end justify-between gap-3"><div><div class="mb-1.5 flex items-center gap-2 text-[13px] text-[#89959a]"><i class="size-1.5 rounded-full bg-[#d89e4c]"></i>{{ current.group }}</div><h1 class="text-2xl font-semibold tracking-normal">{{ title }}</h1><p class="mt-1 text-[13px] text-[#879398]">{{ descriptions[selected] }}</p></div><button class="btn-primary" @click="newEntry"><Plus :size="16" />新建配置</button></div>
          <div v-if="error" class="mb-4 flex items-center gap-2 rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]"><X :size="15" />{{ error }}<button class="ml-auto" @click="error = ''"><X :size="14" /></button></div>
          <div class="mb-3 flex h-12 items-center justify-between rounded border-y border-[#e6ebec] bg-white px-3"><label class="flex flex-1 items-center gap-2 text-[#98a2a6]"><Search :size="16" /><input v-model="query" class="w-full max-w-[360px] border-0 bg-transparent text-[13px] text-[#39474e] outline-none placeholder:text-[#a2acaf]" placeholder="搜索名称或配置内容" /></label><div class="flex items-center gap-3"><small class="text-[13px] text-[#919da1]">{{ filtered.length }} 项</small><button class="btn-secondary compact" @click="load"><Activity :size="14" />刷新</button></div></div>
          <div v-if="loading" class="empty">正在读取配置…</div>
          <div v-else-if="filtered.length" class="overflow-x-auto rounded border border-[#e4e9ea] bg-white"><table class="w-full min-w-[680px] border-collapse text-left"><thead class="bg-[#fafbfb] text-[13px] text-[#929da1]"><tr><th>名称</th><th>状态</th><th>配置摘要</th><th>最近更新</th><th></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id" class="border-t border-[#edf0f1] hover:bg-[#fbfcfc]"><td><div class="flex items-center gap-2.5 py-2"><span class="grid size-7 place-items-center rounded bg-[#eef4f0] text-[#58836d]"><component :is="current.icon" :size="15" /></span><span><b class="block text-[13px] font-semibold text-[#48565d]">{{ item.name }}</b><small class="font-mono text-[13px] text-[#a0aaad]">{{ item.id.slice(0, 8) }}</small></span></div></td><td><button class="status" :class="item.enabled ? 'ok' : 'off'" :disabled="selected === 'adapters'" @click="toggle(item)"><i></i>{{ selected === 'adapters' ? '未连接' : item.enabled ? '已启用' : '已停用' }}</button></td><td><span class="block max-w-[250px] overflow-hidden text-ellipsis whitespace-nowrap font-mono text-[13px] text-[#849095]">{{ item.detail || '无附加配置' }}</span></td><td class="whitespace-nowrap text-[13px] text-[#909b9f]">{{ new Date(item.updatedAt).toLocaleString('zh-CN', { dateStyle: 'medium', timeStyle: 'short' }) }}</td><td><div class="flex justify-end gap-1"><button v-if="selected === 'adapters'" class="row-action" title="启动适配器" @click="startAdapter(item)"><Radio :size="15" /></button><button class="row-action" title="编辑" @click="edit(item)"><Settings2 :size="15" /></button><button class="row-action danger" title="删除" @click="remove(item)"><Trash2 :size="15" /></button></div></td></tr></tbody></table></div>
          <div v-else class="empty"><span class="mb-3 grid size-10 place-items-center rounded-lg bg-[#eef4f0] text-[#59816e]"><component :is="current.icon" :size="21" /></span><b>{{ query ? '没有匹配的项目' : `还没有${title}配置` }}</b><p>{{ query ? '尝试其他关键词。' : '创建第一条配置以开始管理。' }}</p><button v-if="!query" class="btn-primary mt-3" @click="newEntry"><Plus :size="15" />新建配置</button></div>
          <p class="mt-3 flex items-center gap-1.5 text-[13px] text-[#9ba5a8]"><Shield :size="13" />数据保存在服务端数据库中。运行时行为依赖对应的协议或功能引擎。</p>
        </section>
      </div>
    </main>
    <div v-if="modal" class="fixed inset-0 z-20 grid place-items-center bg-[#18252c80] p-4" @click.self="modal = false"><section class="w-full max-w-[480px] rounded-md border border-[#e2e8e9] bg-white p-5 shadow-2xl"><div class="mb-5 flex items-start justify-between"><div><small class="text-[13px] text-[#89959a]">{{ editing ? '编辑' : '新建' }}配置</small><h2 class="mt-1 text-[17px] font-semibold">{{ editing ? '更新' : '添加' }}{{ title }}</h2></div><button class="icon-btn" title="关闭" @click="modal = false"><X :size="18" /></button></div><form class="flex flex-col gap-3" @submit.prevent="save"><label class="field">显示名称<input v-model="name" required maxlength="120" placeholder="输入名称" /></label><label v-if="selected === 'adapters'" class="field">协议类型<select v-model="adapterType"><option value="Onebot11">OneBot 11</option><option value="Milky">Milky</option><option value="Telegram">Telegram</option><option value="OpenQQ">OpenQQ</option></select></label><label class="field">配置 JSON<textarea v-model="detail" rows="8" spellcheck="false"></textarea><small>敏感凭据请使用环境变量或安全配置管理。</small></label><label v-if="selected !== 'adapters'" class="flex items-center justify-between text-[13px]"><span>启用配置</span><input v-model="enabled" type="checkbox" class="accent-[#315f4a]" /></label><div class="mt-2 flex justify-end gap-2 border-t border-[#edf0f0] pt-3"><button type="button" class="btn-secondary" @click="modal = false">取消</button><button class="btn-primary" type="submit"><Check :size="15" />保存配置</button></div></form></section></div>
    <Transition><div v-if="toast" class="fixed bottom-5 right-5 z-30 flex items-center gap-2 rounded bg-[#234b3e] px-3 py-2.5 text-[13px] text-white shadow-lg"><Check :size="15" />{{ toast }}</div></Transition>
  </div>
</template>
